package com.example.billing.api;import static com.example.billing.api.Contracts.*;import com.example.billing.service.CustomerService;import java.net.URI;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/customers")public class CustomerController{private final CustomerService s;public CustomerController(CustomerService s){this.s=s;}@PostMapping ResponseEntity<?> create(@RequestBody CreateCustomerRequest r){try{var x=s.create(r);return ResponseEntity.created(URI.create("/customers/"+x.id())).body(x);}catch(IllegalArgumentException e){return ResponseEntity.badRequest().body(new ApiError("invalid_customer",e.getMessage()));}catch(IllegalStateException e){return ResponseEntity.status(409).body(new ApiError("customer_email_already_exists",e.getMessage()));}}@GetMapping("/{id}")ResponseEntity<?> get(@PathVariable UUID id){var x=s.get(id);return x==null?CatalogController.notFound("customer_not_found","Customer does not exist."):ResponseEntity.ok(x);}@GetMapping List<CustomerResponse> list(){return s.list();}}
